catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading || newValue == '') {
      return;
   }  
	var inc = g_form.getValue('inc_date_time');
	var inj = g_form.getValue('inc_date_initial_inj');
	var format = g_user_date_time_format;	
 	var inc_date = getDateFromFormat(inc,format);
	var inj_date = getDateFromFormat(inj, format);

	if (inc_date == 0){
		g_form.setValue('inc_date_initial_inj', '');	
		if (g_lang == "en"){
			g_form.showFieldMsg("inc_date_initial_inj","Please specify the 'Date and time of the incident' before the 'Date of initial injury/illness'");
		}
		else
		{
			g_form.showFieldMsg("inc_date_initial_inj","Veuillez remplir 'Date et heure de l'incident' avant 'Date de la blessure/maladie initiale'");		
		}
		return;
	}
	if(inj_date>inc_date){ //23< 22
		g_form.setValue('inc_date_initial_inj', '');	
		if (g_lang == "en"){
			g_form.showFieldMsg("inc_date_initial_inj","'Date of initial injury/illness' cannot be after 'Date and time of the incident'");
		}
		else
		{
			g_form.showFieldMsg("inc_date_initial_inj","'Date de la blessure/maladie initiale' ne peut pas être après 'Date et heure de l'incident'");
		}
		return;
	}
}
